static char *
gldelf32_spu_get_script (int *isfile)
{
  *isfile = 1;

  if (bfd_link_relocatable (&link_info) && config.build_constructors)
    return "ldscripts/elf32_spu.xu";
  else if (bfd_link_relocatable (&link_info))
    return "ldscripts/elf32_spu.xr";
  else if (!config.text_read_only)
    return "ldscripts/elf32_spu.xbn";
  else if (!config.magic_demand_paged)
    return "ldscripts/elf32_spu.xn";
  else if (link_info.combreloc && link_info.relro
	   && (link_info.flags & DF_BIND_NOW))
    {
      if (link_info.separate_code)
	return "ldscripts/elf32_spu.xwe";
      else
	return "ldscripts/elf32_spu.xw";
    }
  else if (link_info.combreloc)
    {
      if (link_info.separate_code)
	return "ldscripts/elf32_spu.xce";
      else
	return "ldscripts/elf32_spu.xc";
    }
  else
    {
      if (link_info.separate_code)
	return "ldscripts/elf32_spu.xe";
      else
	return "ldscripts/elf32_spu.x";
    }
}

 
